-- Correct crypto benchmark stress wording to match the accepted OKX feed route.

UPDATE trading_registry
SET payload = 'one_frozen_benchmark_episode_panel;fixed_component_weights;asset_class_and_theme_bucket_required;component_role_required;hot_thematic_single_name_coverage_required;crypto_minority_sleeve_required;controlled_data_stress_sleeve_allowed;critical_data_stress_tags_require_stress_role;missing_crypto_quote_order_book_context_allowed;missing_layer2_stress_component_allowed;stress_exception_ref_required;stress_sleeve_weight_cap_15_percent;non_etf_targets_require_target_context_review;formal_run_once_after_training;benchmark_data_evaluation_only;target_window_training_exclusion_required;same_target_overlapping_folds_blocked;fixed_data_snapshot;fixed_cost_model;fixed_baselines;guardrails_do_not_replace_primary;new_benchmark_requires_new_contract',
    note = 'Primary evaluation benchmark policy. Fold-to-fold comparison uses one frozen episode panel with fixed target/window components, asset-class and theme-bucket metadata, component roles, controlled hot thematic single-name coverage, a small crypto sleeve, and fixed weights. A capped stress sleeve may model critical data-edge cases such as crypto missing quote/order-book context or missing Layer 2 context only with explicit stress role, data-availability tags, and stress-exception refs. OKX crypto trades are transient inputs for trade-derived liquidity bars, not default standalone final saved outputs. Non-ETF targets require reviewed target-context/proxy refs unless an accepted stress exception applies. Benchmark data is evaluation-only and any same-target training fold that overlaps a benchmark component window is blocked.',
    updated_at = NOW()
WHERE key = 'EVALUATION_PRIMARY_BENCHMARK_POLICY';
